'use strict';
// A Polestar_Nav folder's Nav/Chokepoints.lua (generated by `nav pack`, tools/lib/nav/chokepoints.js; Nav/Walk.lua
// splits a walk into named steps at them): read, sanity-checked, and matched against drawn lines.
//
//   load(navDir | file) -> { 0: [cp], 1: [cp] } | null (no file); cp = the file's entry plus i (its 1-based index)
//   passed(pts, list) -> [{ i, at }] the chokepoints a drawn line passes, in order along it (at: yards from its start):
//     within r + 2 flat yd of the line, and within 8 yd of its height where both heights are known
//   liftRide(passes, list, from) -> the first lift ride on the line from its `from` end ('top' | 'bottom') to the
//     other end of the same lift (its pair, or an opposite end with the same liftObject) later along it, or null
//   sanity(cps, { grid, areas }) -> { counts: { <c>: { <kind>: n } }, problems: [text] }
//     lifts: an end without a pair, a pair out of range, not the opposite end of the same lift, a top not 10 yd above
//     its bottom, ends more than 25 yd apart; bridges: not two sides, a side with no area, a side further than r + 60
//     yd, sides not on opposite sides (less than 90 deg apart seen from the middle), a side whose zoneArea is not an
//     AreaTable id (areas: Set of ids, when given); every entry: off the grid (no surface within 3 yd of its height in
//     its column or the 8 around it, our grid; null without one).
//   CURATED: passages players use (lift objects, named bridges and gates) that a file should hold.

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const { findInterpreter } = require('./run');

// Read the Lua file with the Lua interpreter and print JSON (a minimal encoder).
const DUMP = `
local f = assert(arg[1])
PolestarNavChokepoints = nil
dofile(f)
local function enc(v)
	local t = type(v)
	if t == "number" then return string.format("%.17g", v) end
	if t == "string" then return '"' .. v:gsub('[%c"\\\\]', function(c) return string.format("\\\\u%04x", c:byte()) end) .. '"' end
	if t == "boolean" then return tostring(v) end
	if t == "table" then
		if #v > 0 or next(v) == nil then
			local o = {}
			for i = 1, #v do o[i] = enc(v[i]) end
			return "[" .. table.concat(o, ",") .. "]"
		end
		local o = {}
		for k, x in pairs(v) do o[#o + 1] = enc(tostring(k)) .. ":" .. enc(x) end
		return "{" .. table.concat(o, ",") .. "}"
	end
	return "null"
end
local out = {}
for c, list in pairs(PolestarNavChokepoints or {}) do out[#out + 1] = enc(tostring(c)) .. ":" .. enc(list) end
io.write("{" .. table.concat(out, ",") .. "}")
`;

function load(where) {
	const file = fs.existsSync(where) && fs.statSync(where).isDirectory() ? path.join(where, 'Nav', 'Chokepoints.lua') : where;
	if (!fs.existsSync(file)) return null;
	const tmp = path.join(os.tmpdir(), `polestar-chokedump-${process.pid}.lua`);
	fs.writeFileSync(tmp, DUMP);
	try {
		const r = spawnSync(findInterpreter(), [tmp, file], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
		if (r.status !== 0) throw new Error(`reading ${file}: ${r.stderr.trim()}`);
		const raw = JSON.parse(r.stdout || '{}');
		const out = {};
		for (const [c, list] of Object.entries(raw)) out[c] = list.map((cp, k) => ({ ...cp, i: k + 1 }));
		return out;
	} finally {
		fs.rmSync(tmp, { force: true });
	}
}

function passed(pts, list) {
	const out = [];
	if (!list || pts.length < 2) return out;
	let along = 0;
	const best = new Map();
	for (let k = 1; k < pts.length; k++) {
		const [ax, ay, az] = pts[k - 1];
		const [bx, by, bz] = pts[k];
		const dx = bx - ax;
		const dy = by - ay;
		const l2 = dx * dx + dy * dy;
		const L = Math.sqrt(l2);
		for (const cp of list) {
			const t = l2 ? Math.max(0, Math.min(1, ((cp.wx - ax) * dx + (cp.wy - ay) * dy) / l2)) : 0;
			const d = Math.hypot(ax + dx * t - cp.wx, ay + dy * t - cp.wy);
			if (d > cp.r + 2) continue;
			if (typeof az === 'number' && typeof bz === 'number' && typeof cp.z === 'number' && Math.abs(az + (bz - az) * t - cp.z) > 8) continue;
			const at = along + L * t;
			const b = best.get(cp.i);
			if (!b || d < b.d) best.set(cp.i, { i: cp.i, at, d });
		}
		along += L;
	}
	for (const v of best.values()) out.push({ i: v.i, at: +v.at.toFixed(1) });
	return out.sort((a, b) => a.at - b.at);
}

const otherEnd = (list, a) => {
	const want = a.liftEnd === 'top' ? 'bottom' : 'top';
	return list.filter((b) => b.kind === 'lift' && b.liftEnd === want && (b.i === a.pair || (a.liftObject !== undefined && b.liftObject === a.liftObject)));
};

function liftRide(passes, list, from) {
	const byI = new Map(list.map((cp) => [cp.i, cp]));
	for (const p of passes) {
		const a = byI.get(p.i);
		if (!a || a.kind !== 'lift' || a.liftEnd !== from) continue;
		const ends = new Set(otherEnd(list, a).map((b) => b.i));
		const b = passes.find((q) => q.at > p.at && ends.has(q.i));
		if (b) return { from: a, to: byI.get(b.i) };
	}
	return null;
}

function sanity(cps, { grid = null, areas = null } = {}) {
	const counts = {};
	const problems = [];
	const { cellOf, TILE_CELLS, FLAG } = require('../grid/format');
	for (const [c, list] of Object.entries(cps)) {
		counts[c] = {};
		for (const cp of list) {
			counts[c][cp.kind] = (counts[c][cp.kind] || 0) + 1;
			const tag = `${c}#${cp.i} ${cp.kind} "${cp.name}"${cp.lift ? ` ${cp.lift} ${cp.liftEnd}` : ''} (${cp.wx}, ${cp.wy}, ${cp.z})`;
			if (cp.kind === 'lift') {
				const p = cp.pair !== undefined ? list[cp.pair - 1] : null;
				if (cp.pair === undefined) problems.push(`${tag}: a lift end without a pair`);
				else if (!p) problems.push(`${tag}: pair ${cp.pair} out of range`);
				else {
					if (p.kind !== 'lift' || p.liftEnd === cp.liftEnd || (cp.liftObject !== undefined && p.liftObject !== cp.liftObject)) problems.push(`${tag}: pair ${cp.pair} is not the other end of the same lift (${p.kind} ${p.liftEnd} ${p.liftObject})`);
					const top = cp.liftEnd === 'top' ? cp : p;
					const bottom = cp.liftEnd === 'top' ? p : cp;
					if (p.kind === 'lift' && top.z - bottom.z < 10) problems.push(`${tag}: its top is ${(top.z - bottom.z).toFixed(1)} yd above its bottom (want 10+)`);
					if (Math.hypot(p.wx - cp.wx, p.wy - cp.wy) > 25) problems.push(`${tag}: its pair is ${Math.hypot(p.wx - cp.wx, p.wy - cp.wy).toFixed(0)} yd away`);
				}
			}
			if (cp.kind === 'bridge') {
				const s = cp.sides || [];
				if (s.length !== 2) problems.push(`${tag}: ${s.length} sides (want 2)`);
				for (const side of s) {
					if (!side.area) problems.push(`${tag}: a side without an area`);
					const d = Math.hypot(side.wx - cp.wx, side.wy - cp.wy);
					if (d > cp.r + 60) problems.push(`${tag}: a side ${d.toFixed(0)} yd from the middle (r ${cp.r})`);
					if (areas && side.zoneArea !== undefined && !areas.has(side.zoneArea)) problems.push(`${tag}: side zoneArea ${side.zoneArea} is no AreaTable id`);
				}
				if (s.length === 2) {
					const ang = Math.acos(Math.max(-1, Math.min(1, ((s[0].wx - cp.wx) * (s[1].wx - cp.wx) + (s[0].wy - cp.wy) * (s[1].wy - cp.wy)) / (Math.hypot(s[0].wx - cp.wx, s[0].wy - cp.wy) * Math.hypot(s[1].wx - cp.wx, s[1].wy - cp.wy) || 1)))) * (180 / Math.PI);
					if (ang < 90) problems.push(`${tag}: its sides are ${ang.toFixed(0)} deg apart seen from the middle (want opposite)`);
				}
			}
			if (grid && typeof cp.z === 'number') {
				let best = Infinity;
				for (let ox = -1; ox <= 1; ox++) {
					for (let oy = -1; oy <= 1; oy++) {
						const { col, row, i, j } = cellOf(cp.wx + ox * 2.0833, cp.wy + oy * 2.0833);
						const t = grid.tile(+c, col, row);
						if (!t) continue;
						const k = j * TILE_CELLS + i;
						for (let e = t.first[k]; e < t.first[k + 1]; e++) if (!(t.flags[e] & FLAG.BLOCKED)) best = Math.min(best, Math.abs(t.z[e] - cp.z));
					}
				}
				if (best > 3) problems.push(`${tag}: off the grid (nearest walkable surface ${best === Infinity ? 'none' : `${best.toFixed(1)} yd`} from its height)`);
			}
		}
	}
	return { counts, problems };
}

// Passages players use (routes.json lift legs, reported walks, the travel data's lifts), by what identifies them.
const CURATED = [
	{ c: 0, label: 'the Undervator (Ruins of Lordaeron <-> Undercity), 3 lifts', kind: 'lift', liftObjects: [20649, 20652, 20655] },
	{ c: 0, label: "Gnomeregan's Vator", kind: 'lift', liftObjects: [80023] },
	{ c: 0, label: "the Cauldron's scaffold cars", kind: 'lift', liftObjects: [149045, 149046] },
	{ c: 1, label: "Thunder Bluff's Mesa Elevators, 4 lifts", kind: 'lift', liftObjects: [4170, 4171, 47296, 47297] },
	{ c: 1, label: 'the Great Lift and Freewind Post (Barrens <-> Thousand Needles)', kind: 'lift', liftObjects: [11898, 11899] },
	{ c: 1, label: "Darkcloud Pinnacle's rope bridges (#374)", kind: 'bridge', near: [-4900, -1950], within: 450 },
	{ c: 1, label: "Orgrimmar's gate tunnel (Durotar <-> the Valley of Strength)", kind: ['tunnel', 'gate', 'pass'], near: [1430, -4400], within: 200 },
	{ c: 0, label: 'Menethil Harbor bridges', kind: 'bridge', near: [-3750, -800], within: 300 },
	{ c: 0, label: 'Booty Bay (the tunnel in, the bridges)', kind: ['bridge', 'tunnel', 'pass'], near: [-14420, 450], within: 250 },
	{ c: 0, label: 'Stormwind gate and canal bridges', kind: ['bridge', 'gate'], near: [-8700, 650], within: 500 },
	{ c: 0, label: 'Thandol Span (Wetlands <-> Arathi)', kind: ['bridge', 'pass'], near: [-2368, -2519], within: 150 },
	{ c: 0, label: 'the Deeprun Tram entrance (Stormwind)', kind: ['tunnel', 'building', 'gate'], near: [-8346, 514], within: 60 },
];

function curated(cps) {
	return CURATED.map((k) => {
		const list = (cps && cps[k.c]) || [];
		const kinds = [].concat(k.kind);
		const hits = list.filter((cp) => kinds.includes(cp.kind) && (k.liftObjects ? k.liftObjects.includes(cp.liftObject) : Math.hypot(cp.wx - k.near[0], cp.wy - k.near[1]) <= k.within));
		const missing = k.liftObjects ? k.liftObjects.filter((o) => !hits.some((h) => h.liftObject === o)) : [];
		return { label: k.label, found: hits.length, missing };
	});
}

// Passages a set of drawn lines use from a reference file that a candidate file lacks (no entry of the same kind
// within max(r, 25) yd and 15 yd of height): [{ c, cp, routes }] by the number of lines passing it.
function usedMissing(lines, ref, cand) {
	const used = new Map();
	for (const { map, pts } of lines) {
		for (const p of passed(pts, ref[map])) {
			const key = `${map}|${p.i}`;
			used.set(key, (used.get(key) || 0) + 1);
		}
	}
	const out = [];
	for (const [key, n] of used) {
		const [c, i] = key.split('|').map(Number);
		const cp = ref[c][i - 1];
		const has = ((cand && cand[c]) || []).some((x) => x.kind === cp.kind && Math.hypot(x.wx - cp.wx, x.wy - cp.wy) <= Math.max(cp.r, 25) && Math.abs(x.z - cp.z) <= 15);
		if (!has) out.push({ c, cp, routes: n });
	}
	return out.sort((a, b) => b.routes - a.routes);
}

module.exports = { load, passed, liftRide, sanity, curated, usedMissing, CURATED };
